{
  "sections": [
    {
      "no": "2.1",
      "start": 4,
      "end": 8,
      "title": "宣读本周正道经文约伯记一章1至8节，难解的部分尽力为弟兄姊妹解释"
    },
    {
      "no": "2.2",
      "start": 9,
      "end": 18,
      "title": "约伯记1章1至5节：乌斯地的约伯完全正直敬畏神，家产丰厚，儿女设摆筵席，约伯清早为他们献燔祭"
    },
    {
      "no": "2.3",
      "start": 19,
      "end": 25,
      "title": "约伯记1章6至8节：神的众子与撒但侍立耶和华面前，耶和华问撒但从何而来，并称许约伯完全正直"
    }
  ],
  "changes": [],
  "uncertain": []
}

{
  "sections": [
    {
      "no": "3.1",
      "start": 26,
      "end": 33,
      "title": "开场祷告：求神临格开通会众耳朵，赐下使徒先知所传福音、古旧信仰与一切知识，使其真信心生根并多结果子"
    }
  ],
  "changes": [],
  "uncertain": []
}

{
  "sections": [
    {
      "no": "4.1",
      "start": 34,
      "end": 48,
      "title": "讲道分两部分：1至5节看约伯的现实背景是东方富户，6至8节看他的属灵背景是被撒旦控告却被耶和华认可"
    },
    {
      "no": "4.2",
      "start": 49,
      "end": 54,
      "title": "陈社炳自我介绍，服侍任务是不拘传统宣讲先知使徒的福音，并使之成为会众敬拜的根基"
    },
    {
      "no": "4.3",
      "start": 55,
      "end": 67,
      "title": "选约伯记的理由：教会只关注个人祸福而非国度，约伯记能消除顽固观念，是智慧书第一卷，主题为认识耶和华"
    },
    {
      "no": "4.4",
      "start": 68,
      "end": 79,
      "title": "约伯记开篇讨论的两个问题：世界上存不存在绝对的平安，上帝认可的信仰是否意味着远离灾祸"
    }
  ],
  "changes": [
    {
      "type": "retitle",
      "start": 55,
      "end": 67,
      "problems": ["标题超长"],
      "detail": "原标题52字，不在25-50字之间；新标题精简至49字，内容不变"
    },
    {
